request.config:
payload:
  default:
    - models: [{name: "kimi-*", protocol: openai}]
      params: {temperature: 1.0, n: 1, user: "default-user"}
    - models: [{name: "kimi-*", protocol: openai-response}]
      params: {store: true, parallel_tool_calls: false}
  override:
    - models: [{name: "kimi-k3(high)"}]
      params: {requested_hit: true}
    - models: [{name: "kimi-*", protocol: codex}]
      params: {wrong_protocol: true}
    - models: [{name: "kimi-*", from-protocol: openai}]
      params: {from_openai: true}
  filter:
    - models: [{name: "kimi-*", protocol: openai}]
      params: [max_tokens]
